-- CleanupRepository.countDuplicates
with
  "g" as (
    select
      "asset"."duplicateId",
      sum(coalesce("asset_exif"."fileSizeInByte", 0)) - max(coalesce("asset_exif"."fileSizeInByte", 0)) as "reclaim"
    from
      "asset"
      left join "asset_exif" on "asset_exif"."assetId" = "asset"."id"
    where
      "asset"."ownerId" = $1
      and "asset"."duplicateId" is not null
      and "asset"."deletedAt" is null
      and "asset"."visibility" in ('archive', 'timeline')
      and "asset"."stackId" is null
    group by
      "asset"."duplicateId"
    having
      count("asset"."id") > $2
  )
select
  count(*) as "count",
  coalesce(sum("reclaim"), 0) as "bytes"
from
  "g"

