-- CleanupRepository.getBurstClipDistances
select
  p.id,
  (a.embedding <=> b.embedding) as d
from
  unnest($1::uuid[], $2::uuid[]) as p (id, first)
  join smart_search a on a."assetId" = p.id
  join smart_search b on b."assetId" = p.first

-- CleanupRepository.countBursts
with
  "ordered" as (
    select
      "asset"."id" as "id",
      "asset"."localDateTime" as "t",
      "asset_exif"."autoStackId" as "s",
      coalesce("asset_exif"."fileSizeInByte", 0) as "size",
      lag("asset"."localDateTime") over (
        order by
          "asset"."localDateTime",
          "asset"."id"
      ) as "prevT",
      lag("asset_exif"."autoStackId") over (
        order by
          "asset"."localDateTime",
          "asset"."id"
      ) as "prevS"
    from
      "asset"
      left join "asset_exif" on "asset_exif"."assetId" = "asset"."id"
    where
      "asset"."type" = 'IMAGE'
      and "asset"."stackId" is null
      and not exists (
        select
          1 as "one"
        from
          "cleanup_decision"
        where
          "cleanup_decision"."assetId" = "asset"."id"
          and "cleanup_decision"."userId" = $1
          and "cleanup_decision"."queue" = 'bursts'
      )
      and "asset"."deletedAt" is null
      and "asset"."visibility" in ('timeline', 'archive')
      and "asset"."isOffline" = false
      and "asset"."libraryId" is null
      and "asset"."ownerId" = $2
  ),
  "flagged" as (
    select
      "ordered"."id",
      "ordered"."t",
      "ordered"."size",
      case
        when "prevT" is null
        or "t" - "prevT" > interval '2 seconds'
        or "prevS" is distinct from "s" then 1
        else 0
      end as "brk"
    from
      "ordered"
  ),
  "grouped" as (
    select
      "flagged"."id",
      "flagged"."size",
      sum("brk") over (
        order by
          "t",
          "id"
      ) as "grp"
    from
      "flagged"
  ),
  "sized" as (
    select
      "grouped"."grp",
      count("grouped"."id") as "n",
      sum("grouped"."size") as "total",
      max("grouped"."size") as "mx"
    from
      "grouped"
    group by
      "grouped"."grp"
    having
      count("grouped"."id") >= $3
  )
select
  count(*) as "count",
  coalesce(sum("total" - "mx"), 0) as "bytes"
from
  "sized"

